const listMyTasks = `-- name: ListMyTasks :many
SELECT
    t.id, t.instance_id, t.node_seq, t.node_name, t.assignee_id, t.status,
    t.comment, t.acted_at, t.created_at,
    i.biz_type, i.biz_id, i.biz_no, i.biz_summary, i.submitter_id,
    i.submitter_name, i.status AS instance_status, i.current_seq, i.submitted_at,
    count(*) OVER () AS total
FROM approval_tasks t
JOIN approval_instances i ON i.id = t.instance_id AND i.tenant_id = t.tenant_id
WHERE t.tenant_id = $1::bigint
  AND t.assignee_id = $2::bigint
  AND ($3::text = '' OR i.biz_type = $3::text)
  AND ($4::text = ''
       OR i.biz_no ILIKE '%' || $4::text || '%'
       OR i.biz_summary::text ILIKE '%' || $4::text || '%'
       OR i.submitter_name ILIKE '%' || $4::text || '%'
       OR t.node_name ILIKE '%' || $4::text || '%')
  AND CASE
        WHEN $5::text = ''        THEN t.status = 'PENDING'
        WHEN $5::text = 'HANDLED' THEN t.status <> 'PENDING'
        ELSE t.status = $5::text
      END
ORDER BY
  CASE WHEN $5::text = '' THEN t.created_at END ASC,
  CASE WHEN $5::text <> '' THEN coalesce(t.acted_at, t.created_at) END DESC,
  t.id DESC
LIMIT $7::int OFFSET $6::int
`

type ListMyTasksParams struct {
	TenantID   int64
	AssigneeID int64
	BizType    string
	Keyword    string
	Status     string
	RowOffset  int32
	RowLimit   int32
}

type ListMyTasksRow struct {
	ID             int64
	InstanceID     int64
	NodeSeq        int32
	NodeName       string
	AssigneeID     int64
	Status         string
	Comment        string
	ActedAt        pgtype.Timestamptz
	CreatedAt      pgtype.Timestamptz
	BizType        string
	BizID          int64
	BizNo          string
	BizSummary     []byte
	SubmitterID    int64
	SubmitterName  string
	InstanceStatus string
	CurrentSeq     int32
	SubmittedAt    pgtype.Timestamptz
	Total          int64
}

// One query serves every tab of "my approvals": the pending queue by
// default, everything already handled, or one exact decision.
// Pending work is oldest first because the fixed HOME1 SLA is measured from
// task creation; handled work remains newest decision first.
func (q *Queries) ListMyTasks(ctx context.Context, arg ListMyTasksParams) ([]ListMyTasksRow, error) {
	rows, err := q.db.Query(ctx, listMyTasks,
		arg.TenantID,
		arg.AssigneeID,
		arg.BizType,
		arg.Keyword,
		arg.Status,
		arg.RowOffset,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListMyTasksRow
	for rows.Next() {
		var i ListMyTasksRow
		if err := rows.Scan(
			&i.ID,
			&i.InstanceID,
			&i.NodeSeq,
			&i.NodeName,
			&i.AssigneeID,
			&i.Status,
			&i.Comment,
			&i.ActedAt,
			&i.CreatedAt,
			&i.BizType,
			&i.BizID,
			&i.BizNo,
			&i.BizSummary,
			&i.SubmitterID,
			&i.SubmitterName,
			&i.InstanceStatus,
			&i.CurrentSeq,
			&i.SubmittedAt,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

